/**
 * generated by stackra gen from stackra.config.ts (targets, pwa.manifest), src/config/pwa.config.ts
 * (caching), src/config/i18n.config.ts (locales, prefixes), src/config/telemetry.config.ts
 * (bundle), src/routes/offline/offline.route.ts (prerender) and runway.yaml (environments.dev:
 * port, host, https; environments.<env>.vars; telemetry.sentryProject) — do not edit
 * Purpose: the Vite config for the three targets. `classComponents()` compiles every
 *          `class X extends Component<P>` under `src/` to a React function component before React
 *          and the React Compiler see it; `@stackra/vite-plugin` then bundles React, Tailwind v4,
 *          the `#stackra/*` virtual modules with HMR, `vite-plugin-pwa` for the pwa target, one
 *          HTML page per locale, the per-locale prerender of the offline page, `base: "./"` and
 *          the renderer output folder for the desktop target, the CSP-safe build (no inlined
 *          asset), hidden sourcemaps uploaded to Sentry, the `safari17` target and the bundle
 *          budgets.
 * Boundary: the dev server block is the member runway's, resolved through `.stackra/dev/ports.json`
 *           (lane offsets applied); no port is typed anywhere else. The service worker's build
 *           (`injectManifest` over the generated `sw.ts`) is owned by Stackra, never a section
 *           key. The class-component pass runs first so lint, types and the compiler all read the
 *           compiled function; its source maps point back to the class lines. The console has no
 *           `vite.extend.ts`, so nothing is merged after the plugins. The gitignored
 *           `vite.config.ts` at the member root re-exports this file.
 * Runtime: node
 */
import { defineConfig } from "vite";
import { classComponents } from "@stackra/gen/vite";
import { definesFor, devServer } from "@stackra/runway/vite";
import { stackra } from "@stackra/vite-plugin";
import app from "../stackra.config";

export default defineConfig(({ mode }) =>
  stackra.viteConfig(app, {
    mode, // web | pwa | desktop, from `stackra build --target`
    // first: class components to function components, with source maps to the class
    plugins: [classComponents({ include: ["src/**/*.tsx"] })],
    // one HTML page per locale, each linking its own manifest (see ./index.html and ./<prefix>/)
    pages: {
      en: { html: ".stackra/index.html", path: "/" },
      "en-US": { html: ".stackra/en-us/index.html", path: "/en-us/" },
      ar: { html: ".stackra/ar/index.html", path: "/ar/" },
      "ar-SA": { html: ".stackra/ar-sa/index.html", path: "/ar-sa/" },
    },
    entry: ".stackra/entry/browser.ts",
    server: devServer("console"), // runway.yaml environments.dev via ports.json
    // vars → import.meta.env.VITE_*
    define: definesFor("console", process.env.STACKRA_ENVIRONMENT ?? "dev"),
    // OfflineRoute `prerender: true`: one static document per locale, hydrated by its own entry
    prerender: {
      entry: ".stackra/entry/offline.ts",
      routes: ["/offline", "/en-us/offline", "/ar/offline", "/ar-sa/offline"],
    },
    pwa: {
      strategies: "injectManifest", // owned: gen writes sw.ts
      srcDir: ".stackra",
      filename: "sw.ts",
      manifests: [
        ".stackra/pwa/manifest.en.webmanifest",
        ".stackra/pwa/manifest.en-us.webmanifest",
        ".stackra/pwa/manifest.ar.webmanifest",
        ".stackra/pwa/manifest.ar-sa.webmanifest",
      ],
      // the prerendered offline pages join the precache with the shell; each revision is its
      // content hash at build time, so a changed page is re-precached
      additionalManifestEntries: "prerender",
    },
    desktop: { base: "./", outDir: "dist/renderer" },
    // telemetry.config.ts budgets.entryKb/routeKb; gzipped; build fails over budget
    budgets: { entryKb: 200, routeKb: 100 },
    // hidden: maps are uploaded to Sentry and never served
    build: { target: "safari17", sourcemap: "hidden", assetsInlineLimit: 0 },
    // runway.yaml telemetry.sentryProject; the upload token is the release job's, never here
    sourcemaps: { upload: "sentry", project: "acme-console" },
  }),
);
